import sys

MOD = 998244353

def solve(data):
    it = iter(map(int, data.split()))
    n = next(it)
    a = [next(it) for _ in range(n - 1)]

    primes = set()
    for x in a:
        y = x
        d = 2
        while d * d <= y:
            if y % d == 0:
                primes.add(d)
                while y % d == 0:
                    y //= d
            d += 1
        if y > 1:
            primes.add(y)

    answer = 1
    for p in primes:
        exponents = []
        total = 0
        for x in a:
            y = x
            e = 0
            while y % p == 0:
                y //= p
                e += 1
            exponents.append(e)
            total += e

        powers = [1] * (n * total + 1)
        for j in range(1, len(powers)):
            powers[j] = powers[j - 1] * p % MOD

        dp = [0] * (total + 1)
        dp[0] = 1
        for i, e in enumerate(exponents):
            nxt = [0] * (total + 1)
            steps = (h - e, h + e) if e else (h,)
            for h, value in enumerate(dp):
                if not value:
                    continue
                for nh in ( (h - e, h + e) if e else (h,) ):
                    if nh >= 0:
                        nxt[nh] = (nxt[nh] + value * powers[nh]) % MOD
                    else:
                        # The new minimum shifts all i+1 prior vertices upward.
                        nxt[0] = (nxt[0] + value * powers[(-nh) * (i + 1)]) % MOD
            dp = nxt

        answer = answer * (sum(dp) % MOD) % MOD

    return str(answer)

print(solve(sys.stdin.read()))

