from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            ending[b].append((a, i))

        gains = [0] * m
        maximum = 0
        second = 0
        maximum_count = 0
        owner = -1
        baseline = 0

        for right in range(1, n + 1):
            for a, index in ending[right]:
                if a > maximum:
                    second = maximum
                    maximum = a
                    maximum_count = 1
                    owner = index
                elif a == maximum:
                    maximum_count += 1
                elif a > second:
                    second = a

            baseline += right - maximum
            if maximum_count == 1:
                gains[owner] += maximum - second

        return baseline + max(gains)

