class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        max_bands = min(n, x)
        dp = [0] * (max_bands + 1)
        dp[0] = 1

        for _ in range(n):
            nxt = [0] * (max_bands + 1)
            for bands, ways in enumerate(dp):
                if not ways:
                    continue
                # Put the performer into one of the existing bands.
                nxt[bands] = (nxt[bands] + ways * bands) % MOD
                # Put the performer on a previously unused stage, creating
                # a new band and choosing its score.
                if bands < max_bands:
                    nxt[bands + 1] = (nxt[bands + 1] +
                                       ways * (x - bands) * y) % MOD
            dp = nxt

        return sum(dp) % MOD

