class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        length = len(s)

        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (length + 1)
        inv_fact[length] = pow(fact[length], MOD - 2, MOD)
        for i in range(length, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def choose(n, r):
            if r < 0 or r > n:
                return 0
            return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

        # If x has c set bits, its first operation produces c.
        # Determine which possible c reach 1 in at most k-1 more operations.
        good = [False] * (length + 1)
        for c in range(1, length + 1):
            value = c
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[c] = steps <= k - 1

        # Scan the bound from left to right. At each 1, choose 0 there
        # and count all suffixes having each acceptable total weight.
        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                for total_ones in range(1, length + 1):
                    if good[total_ones]:
                        answer = (answer + choose(
                            remaining, total_ones - prefix_ones)) % MOD
                prefix_ones += 1

        return answer

