import sys
import heapq


def main():
    inp = sys.stdin.buffer.read().split()
    if not inp:
        return
    n = int(inp[0])
    g = [x.decode() for x in inp[1:1 + n]]
    inf = 10 ** 9
    dist = [[inf] * n for _ in range(n)]
    heap = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
        for j, ch in enumerate(g[i]):
            if ch != '-':
                dist[i][j] = 1
                heapq.heappush(heap, (1, i, j))

    # inc[x][c] are vertices having a c-labelled edge into x;
    # out[y][c] are vertices reached by a c-labelled edge from y.
    inc = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    missing = False
    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch == '-':
                missing = True
            else:
                c = ord(ch) - 97
                out[i][c].append(j)
                inc[j][c].append(i)

    # With no missing edges, every answer is already 0 or 1.
    if missing:
        while heap:
            val, x, y = heapq.heappop(heap)
            if dist[x][y] != val:
                continue
            nv = val + 2
            for c in range(26):
                left = inc[x][c]
                right = out[y][c]
                if not left or not right:
                    continue
                for u in left:
                    row = dist[u]
                    for v in right:
                        if nv < row[v]:
                            row[v] = nv
                            heapq.heappush(heap, (nv, u, v))

    ans = []
    for row in dist:
        ans.append(' '.join('-1' if x == inf else str(x) for x in row))
    sys.stdout.write('\n'.join(ans))


if __name__ == '__main__':
    main()

