import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    upper = [0] * n
    lower = [0] * n
    for i in range(n):
        upper[i] = data[2 + 2 * i]
        lower[i] = data[3 + 2 * i]

    def feasible(h):
        left = max(0, h - lower[0])
        right = upper[0]
        if left > right:
            return False
        for i in range(1, n):
            new_left = max(0, h - lower[i], left - x)
            new_right = min(upper[i], right + x)
            if new_left > new_right:
                return False
            left, right = new_left, new_right
        return True

    lo = 0
    hi = min(u + d for u, d in zip(upper, lower))
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1

    print(sum(upper) + sum(lower) - n * lo)


