class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        total = n * m
        directions = [(-1, 1), (1, 1), (1, -1), (-1, -1)]

        # Number of valid alternating cells starting at each cell in each direction.
        suffix = [array('H', [0]) * total for _ in range(4)]
        for d, (di, dj) in enumerate(directions):
            rows = range(n - 1, -1, -1) if di > 0 else range(n)
            for i in rows:
                cols = range(m - 1, -1, -1) if dj > 0 else range(m)
                for j in cols:
                    ni, nj = i + di, j + dj
                    length = 1
                    if 0 <= ni < n and 0 <= nj < m:
                        expected = 0 if grid[i][j] == 2 else 2
                        if grid[ni][nj] == expected:
                            length += suffix[d][ni * m + nj]
                    suffix[d][i * m + j] = length

        # Number of cells in a valid segment beginning with 1 and ending here.
        prefix = [array('H', [0]) * total for _ in range(4)]
        answer = 0
        for d, (di, dj) in enumerate(directions):
            rows = range(n) if di > 0 else range(n - 1, -1, -1)
            for i in rows:
                cols = range(m) if dj > 0 else range(m - 1, -1, -1)
                for j in cols:
                    k = i * m + j
                    value = grid[i][j]
                    if value == 1:
                        length = 1
                    else:
                        pi, pj = i - di, j - dj
                        length = 0
                        if 0 <= pi < n and 0 <= pj < m:
                            pk = pi * m + pj
                            previous = grid[pi][pj]
                            if prefix[d][pk] and value == (0 if previous == 2 else 2):
                                length = prefix[d][pk] + 1
                    prefix[d][k] = length
                    answer = max(answer, length)

                    # Turn clockwise at this cell, then continue in the new direction.
                    if length:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m:
                            expected = 0 if value == 2 else 2
                            if grid[ni][nj] == expected:
                                turned = length + suffix[(d + 1) % 4][ni * m + nj]
                                answer = max(answer, turned)
        return answer

