from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def completions(odd, even, previous_parity):
            length = odd + even
            if length == 0:
                return 1
            next_parity = 1 - previous_parity
            required_odd = (length + 1) // 2 if next_parity else length // 2
            required_even = length // 2 if next_parity else (length + 1) // 2
            if odd != required_odd or even != required_even:
                return 0
            return fact[odd] * fact[even]

        odd = (n + 1) // 2
        even = n // 2
        total = completions(odd, even, 0) + completions(odd, even, 1)
        if k > total:
            return []

        answer = []
        used = [False] * (n + 1)
        previous = None

        for _ in range(n):
            for value in range(1, n + 1):
                parity = value & 1
                if used[value] or (previous is not None and parity == previous):
                    continue
                new_odd = odd - (parity == 1)
                new_even = even - (parity == 0)
                count = completions(new_odd, new_even, parity)
                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    used[value] = True
                    odd, even, previous = new_odd, new_even, parity
                    break
        return answer

