class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # p[e] is 10**e modulo k.  A digit in the left half contributes
        # at most two powers of ten to the complete palindrome.
        p = [1] * n
        for e in range(1, n):
            p[e] = (p[e - 1] * 10) % k

        coeff = [0] * half
        for i in range(half):
            j = n - 1 - i
            if i == j:
                coeff[i] = p[i]
            else:
                coeff[i] = (p[i] + p[j]) % k

        # suffix[i][r] says that the positions i..half-1 can contribute
        # residue r modulo k.
        suffix = [None] * (half + 1)
        suffix[half] = bytearray(k)
        suffix[half][0] = 1
        for i in range(half - 1, -1, -1):
            nxt = suffix[i + 1]
            cur = bytearray(k)
            a = coeff[i]
            for digit in range(10):
                shift = (a * digit) % k
                for r in range(k):
                    if nxt[r]:
                        cur[(r + shift) % k] = 1
            suffix[i] = cur

        digits = []
        residue = 0
        for i in range(half):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                new_residue = (residue + coeff[i] * digit) % k
                if suffix[i + 1][(-new_residue) % k]:
                    digits.append(str(digit))
                    residue = new_residue
                    break

        left = ''.join(digits)
        return left + left[:n // 2][::-1]

