def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [tuple(data[i:i + 2]) for i in range(2, 2 * n + 2, 2)]

    # In an optimal composition, functions are ordered by increasing
    # B/(A-1) from outermost to innermost.  A=1 is treated as infinity.
    funcs.sort(
        key=lambda f: f[1] / (f[0] - 1) if f[0] > 1 else float('inf'),
        reverse=True,
    )

    dp = [-1] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for used in range(k, 0, -1):
            if dp[used - 1] != -1:
                value = a * dp[used - 1] + b
                if value > dp[used]:
                    dp[used] = value
    print(dp[k])

