class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first, middle, last = p.split('*')
        n = len(s)

        def occurrences(pattern):
            m = len(pattern)
            found = [False] * (n + 1)
            if m == 0:
                return [True] * (n + 1)

            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                prefix[i] = j

            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = prefix[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    found[i - m + 1] = True
                    j = prefix[j - 1]
            return found

        def next_occurrence(found):
            result = [n + 1] * (n + 2)
            for i in range(n, -1, -1):
                result[i] = i if found[i] else result[i + 1]
            return result

        first_occ = occurrences(first)
        middle_next = next_occurrence(occurrences(middle))
        last_next = next_occurrence(occurrences(last))

        answer = n + 1
        first_len, middle_len, last_len = len(first), len(middle), len(last)
        for start in range(n + 1):
            if not first_occ[start] or start + first_len > n:
                continue
            b = middle_next[start + first_len]
            if b > n or b + middle_len > n:
                continue
            c = last_next[b + middle_len]
            if c <= n:
                answer = min(answer, c + last_len - start)

        return -1 if answer == n + 1 else answer

