import sys

def solve_case(n, a, b):
    x = [i for i,c in enumerate(a) if c == '1']
    y = [i for i,c in enumerate(b) if c == '1']
    if len(x) < len(y):
        return -1
    m, q = len(x), len(y)
    def ok(k):
        p = 0
        # Assign a nonempty consecutive block of x to each y.
        for j in range(q):
            if p >= m or abs(x[p] - y[j]) > k:
                return False
            # The next block must start late enough for its displacement,
            # and at a boundary whose gap does not expand.
            if j == q-1:
                return all(abs(z-y[j]) <= k for z in x[p:])
            lim = y[j] + k
            r = p + 1
            while r < m and x[r] <= lim:
                if x[r] >= y[j+1]-k and y[j+1]-y[j] <= x[r]-x[r-1]:
                    break
                r += 1
            if r >= m or x[r] > lim or x[r] < y[j+1]-k:
                return False
            # all pieces before r belong to this target
            if any(z < y[j]-k or z > lim for z in x[p:r]):
                return False
            p = r
        return False
    lo, hi = 0, n-1
    while lo < hi:
        mid = (lo+hi)//2
        if ok(mid): hi = mid
        else: lo = mid+1
    return lo if ok(lo) else -1

