class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        inf = 10**30
        mins = [inf] * k
        mins[0] = 0
        pref = 0
        ans = -inf
        for j, x in enumerate(nums, 1):
            pref += x
            r = j % k
            if mins[r] != inf:
                v = pref - mins[r]
                if v > ans:
                    ans = v
            if pref < mins[r]:
                mins[r] = pref
        return ans

