from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        # A line for index i is dp[i] + (x-i)*nums[i].
        # Li Chao tree stores the maximum of these lines at each x.
        tree = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(node, lo, hi, line):
            current = tree[node]
            if current is None:
                tree[node] = line
                return
            mid = (lo + hi) // 2
            if value(line, mid) > value(current, mid):
                tree[node], line = line, current
            if lo == hi:
                return
            if value(line, lo) > value(tree[node], lo):
                add(node * 2, lo, mid, line)
            else:
                add(node * 2 + 1, mid + 1, hi, line)

        def query(node, lo, hi, x):
            line = tree[node]
            best = value(line, x) if line is not None else -10**30
            if lo == hi:
                return best
            mid = (lo + hi) // 2
            if x <= mid:
                return max(best, query(node * 2, lo, mid, x))
            return max(best, query(node * 2 + 1, mid + 1, hi, x))

        add(1, 0, n - 1, (nums[0], 0))
        score = 0
        for j in range(1, n):
            score = query(1, 0, n - 1, j)
            add(1, 0, n - 1, (nums[j], score - j * nums[j]))
        return score

