import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits - 1

        prime = [True] * (limit + 1)
        prime[0] = prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                prime[p * p::p] = [False] * (((limit - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        infinity = 10 ** 30
        distance = [infinity] * (limit + 1)
        distance[n] = n
        heap = [(n, n)]
        powers = [10 ** i for i in range(digits)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distance[value]:
                continue
            if value == m:
                return cost

            for power in powers:
                digit = (value // power) % 10
                if digit < 9:
                    nxt = value + power
                    if not prime[nxt] and cost + nxt < distance[nxt]:
                        distance[nxt] = cost + nxt
                        heapq.heappush(heap, (distance[nxt], nxt))
                if digit > 0:
                    nxt = value - power
                    if not prime[nxt] and cost + nxt < distance[nxt]:
                        distance[nxt] = cost + nxt
                        heapq.heappush(heap, (distance[nxt], nxt))

        return -1

