from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Z-function of the whole array: z[i] is the LCP of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for k in range(1, n):
            if k <= right:
                z[k] = min(right - k + 1, z[k - left])
            while k + z[k] < n and nums[z[k]] == nums[k + z[k]]:
                z[k] += 1
            if k + z[k] - 1 > right:
                left, right = k, k + z[k] - 1

        # Rolling hashes make each comparison of two equal-length ranges O(1).
        # The 64-bit modulus is implicit in the mask.
        mask = (1 << 64) - 1
        base = 1000003
        power = [1] * (n + 1)
        h = [0] * (n + 1)
        for k, value in enumerate(nums):
            power[k + 1] = (power[k] * base) & mask
            h[k + 1] = (h[k] * base + value + 1) & mask

        answer = 0
        for i in range(1, n - 1):
            first = z[i] >= i
            if first:
                answer += max(0, n - 2 * i)

            # For nums[i:i+b] to prefix nums[i+b:], 2*b elements must remain.
            for b in range(1, (n - i) // 2 + 1):
                left_hash = (h[i + b] - h[i] * power[b]) & mask
                right_hash = (h[i + 2 * b] - h[i + b] * power[b]) & mask
                if left_hash == right_hash:
                    if not (first and b >= i):
                        answer += 1
        return answer

