    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base = s.count('1')
        t = '1' + s + '1'
        best_gain = 0
        i = 1
        n = len(t)

        while i < n - 1:
            if t[i] == '0':
                i += 1
                continue

            # Locate this run of ones.
